[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <meta name="description" content="A tech blog showcasing engineering insights, product updates, and community stories from a cloud deployment platform.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --blue-500: #0072F5;
      --blue-600: #0062D5;
      --blue-50: #EBF5FF;
      --blue-100: #D6EBFF;
      --orange-500: #F97316;
      --orange-600: #EA680C;
      --navy-900: #171717;
      --slate-800: #1E293B;
      --slate-700: #334155;
      --slate-600: #475569;
      --slate-500: #64748B;
      --slate-400: #94A3B8;
      --slate-300: #CBD5E1;
      --slate-200: #E2E8F0;
      --slate-100: #F1F5F9;
      --gray-50: #FAFAFA;
      --gray-100: #F4F4F5;
      --gray-200: #E4E4E7;
      --white: #FFFFFF;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 12px 32px rgba(0,0,0,0.1);
      --radius-sm: 6px;
      --radius-md: 8px;
      --radius-lg: 12px;
      --radius-xl: 16px;
      --transition-fast: 150ms ease;
      --transition-base: 200ms ease;
      --transition-slow: 300ms ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      color: var(--slate-800);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    ul { list-style: none; }
    img { display: block; max-width: 100%; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== SKIP LINK ===== */
    .skip-link {
      position: absolute;
      top: -100%;
      left: 16px;
      background: var(--blue-500);
      color: var(--white);
      padding: 8px 16px;
      border-radius: var(--radius-sm);
      z-index: 10000;
      font-size: 14px;
      font-weight: 600;
    }
    .skip-link:focus { top: 16px; }

    /* ===== HEADER ===== */
    .header {
      position: sticky;
      top: 0;
      z-index: 1000;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--slate-200);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-weight: 800;
      font-size: 18px;
      color: var(--navy-900);
      flex-shrink: 0;
    }

    .logo-icon {
      width: 28px;
      height: 28px;
      background: var(--blue-500);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 16px; height: 16px; }

    .nav { display: flex; align-items: center; gap: 4px; }

    .nav-item {
      position: relative;
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 8px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--slate-700);
      border-radius: var(--radius-sm);
      transition: color var(--transition-fast), background var(--transition-fast);
      white-space: nowrap;
    }

    .nav-item:hover, .nav-item:focus-visible {
      color: var(--navy-900);
      background: var(--slate-100);
    }

    .nav-item svg {
      width: 14px;
      height: 14px;
      transition: transform var(--transition-fast);
    }

    .nav-item[aria-expanded="true"] svg { transform: rotate(180deg); }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }

    .btn-ask-ai {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 7px 14px;
      font-size: 13px;
      font-weight: 600;
      color: var(--blue-500);
      background: var(--blue-50);
      border-radius: var(--radius-md);
      transition: background var(--transition-fast), color var(--transition-fast);
    }

    .btn-ask-ai:hover { background: var(--blue-100); }
    .btn-ask-ai svg { width: 14px; height: 14px; }

    .btn-login {
      padding: 7px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--slate-700);
      border-radius: var(--radius-md);
      transition: color var(--transition-fast), background var(--transition-fast);
    }

    .btn-login:hover { color: var(--navy-900); background: var(--slate-100); }

    .btn-signup {
      padding: 7px 16px;
      font-size: 14px;
      font-weight: 600;
      color: var(--white);
      background: var(--navy-900);
      border-radius: var(--radius-md);
      transition: background var(--transition-fast);
    }

    .btn-signup:hover { background: var(--slate-700); }

    /* ===== MEGA MENU ===== */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      min-width: 640px;
      background: var(--white);
      border: 1px solid var(--slate-200);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      padding: 24px;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      transition: opacity var(--transition-base), visibility var(--transition-base);
      z-index: 2000;
    }

    .mega-menu.is-open {
      opacity: 1;
      visibility: visible;
      pointer-events: auto;
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .mega-menu-col h4 {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--slate-400);
      margin-bottom: 12px;
      padding-bottom: 8px;
      border-bottom: 1px solid var(--slate-200);
    }

    .mega-menu-col ul { display: flex; flex-direction: column; gap: 2px; }

    .mega-menu-link {
      display: flex;
      flex-direction: column;
      padding: 8px 10px;
      border-radius: var(--radius-sm);
      transition: background var(--transition-fast);
    }

    .mega-menu-link:hover { background: var(--slate-100); }

    .mega-menu-link-title {
      font-size: 14px;
      font-weight: 600;
      color: var(--navy-900);
    }

    .mega-menu-link-desc {
      font-size: 12px;
      color: var(--slate-500);
      line-height: 1.4;
      margin-top: 2px;
    }

    .resources-menu { min-width: 480px; }

    /* ===== HERO ===== */
    .hero {
      padding: 64px 0 0;
      text-align: center;
    }

    .hero h1 {
      font-size: 48px;
      font-weight: 800;
      color: var(--navy-900);
      letter-spacing: -0.025em;
      line-height: 1.1;
    }

    .hero p {
      margin-top: 16px;
      font-size: 18px;
      color: var(--slate-500);
      max-width: 560px;
      margin-left: auto;
      margin-right: auto;
      line-height: 1.6;
    }

    /* ===== CATEGORY FILTERS ===== */
    .filters-section {
      padding: 40px 0 0;
      position: relative;
    }

    .filters-bar {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    .category-pills {
      display: flex;
      align-items: center;
      gap: 6px;
      flex-wrap: wrap;
      flex: 1;
    }

    .pill {
      padding: 7px 16px;
      font-size: 13px;
      font-weight: 500;
      color: var(--slate-600);
      background: var(--gray-50);
      border: 1px solid var(--slate-200);
      border-radius: 999px;
      transition: all var(--transition-fast);
      white-space: nowrap;
    }

    .pill:hover {
      color: var(--navy-900);
      border-color: var(--slate-300);
      background: var(--white);
    }

    .pill:focus-visible {
      outline: 2px solid var(--blue-500);
      outline-offset: 2px;
    }

    .pill.is-active {
      color: var(--white);
      background: var(--navy-900);
      border-color: var(--navy-900);
    }

    .search-wrapper {
      position: relative;
      flex-shrink: 0;
    }

    .search-wrapper svg {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      color: var(--slate-400);
      pointer-events: none;
    }

    .search-input {
      padding: 8px 14px 8px 36px;
      font-size: 13px;
      font-family: inherit;
      color: var(--slate-800);
      background: var(--gray-50);
      border: 1px solid var(--slate-200);
      border-radius: 999px;
      outline: none;
      width: 200px;
      transition: border-color var(--transition-fast), box-shadow var(--transition-fast), width var(--transition-slow);
    }

    .search-input::placeholder { color: var(--slate-400); }

    .search-input:focus {
      border-color: var(--blue-500);
      box-shadow: 0 0 0 3px rgba(0,114,245,0.15);
      width: 260px;
    }

    /* ===== FEATURED ARTICLES ===== */
    .featured-section {
      padding: 48px 0 0;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      grid-template-rows: auto auto;
      gap: 20px;
    }

    .featured-card {
      position: relative;
      background: var(--white);
      border: 1px solid var(--slate-200);
      border-radius: var(--radius-xl);
      padding: 32px;
      transition: border-color var(--transition-base), box-shadow var(--transition-base);
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      overflow: hidden;
    }

    .featured-card:hover {
      border-color: var(--slate-300);
      box-shadow: var(--shadow-md);
    }

    .featured-card:focus-visible {
      outline: 2px solid var(--blue-500);
      outline-offset: 2px;
    }

    .featured-card--main {
      grid-column: 1 / 2;
      grid-row: 1 / 3;
      background: linear-gradient(135deg, #0a1628 0%, #0f2440 100%);
      border-color: transparent;
      color: var(--white);
      min-height: 440px;
    }

    .featured-card--main:hover {
      box-shadow: 0 16px 48px rgba(10,22,40,0.3);
    }

    .featured-card--main .featured-tag { background: rgba(0,114,245,0.2); color: #60a5fa; }
    .featured-card--main .featured-date { color: rgba(255,255,255,0.6); }
    .featured-card--main .featured-title { color: var(--white); }
    .featured-card--main .featured-excerpt { color: rgba(255,255,255,0.7); }
    .featured-card--main .featured-author-name { color: rgba(255,255,255,0.8); }

    .featured-card--side {
      min-height: 210px;
    }

    .featured-tag {
      display: inline-block;
      padding: 4px 10px;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      background: var(--blue-50);
      color: var(--blue-500);
      border-radius: 999px;
      width: fit-content;
      margin-bottom: 16px;
    }

    .featured-date {
      font-size: 13px;
      color: var(--slate-500);
      margin-bottom: 8px;
    }

    .featured-title {
      font-size: 22px;
      font-weight: 700;
      line-height: 1.3;
      color: var(--navy-900);
      letter-spacing: -0.01em;
      margin-bottom: 12px;
    }

    .featured-card--main .featured-title {
      font-size: 28px;
    }

    .featured-excerpt {
      font-size: 14px;
      line-height: 1.65;
      color: var(--slate-600);
      margin-bottom: 20px;
      flex: 1;
    }

    .featured-author {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: auto;
    }

    .featured-avatar {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
      font-weight: 600;
      flex-shrink: 0;
    }

    .featured-card--main .featured-avatar { background: rgba(0,114,245,0.3); color: #93bbfd; }
    .featured-card--side .featured-avatar { background: var(--blue-50); color: var(--blue-500); }

    .featured-author-name {
      font-size: 13px;
      font-weight: 600;
      color: var(--slate-700);
    }

    /* ===== AGENTIC STATS ===== */
    .stats-bar {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
      padding: 32px 0;
    }

    .stat-item {
      background: var(--gray-50);
      border: 1px solid var(--slate-200);
      border-radius: var(--radius-lg);
      padding: 20px;
      text-align: center;
      transition: border-color var(--transition-fast);
    }

    .stat-item:hover { border-color: var(--slate-300); }

    .stat-value {
      font-size: 28px;
      font-weight: 800;
      color: var(--blue-500);
      letter-spacing: -0.02em;
      line-height: 1.2;
    }

    .stat-label {
      font-size: 12px;
      color: var(--slate-500);
      margin-top: 6px;
      line-height: 1.4;
    }

    /* ===== LATEST NEWS ===== */
    .latest-section {
      padding: 32px 0;
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 24px;
    }

    .section-title {
      font-size: 24px;
      font-weight: 700;
      color: var(--navy-900);
      letter-spacing: -0.01em;
    }

    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .news-card {
      background: var(--white);
      border: 1px solid var(--slate-200);
      border-radius: var(--radius-lg);
      padding: 24px;
      display: flex;
      flex-direction: column;
      transition: border-color var(--transition-base), box-shadow var(--transition-base);
    }

    .news-card:hover {
      border-color: var(--slate-300);
      box-shadow: var(--shadow-md);
    }

    .news-card:focus-visible {
      outline: 2px solid var(--blue-500);
      outline-offset: 2px;
    }

    .news-tag {
      display: inline-block;
      padding: 3px 10px;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      background: var(--gray-100);
      color: var(--slate-600);
      border-radius: 999px;
      width: fit-content;
      margin-bottom: 12px;
    }

    .news-tag--engineering { background: #FEF3C7; color: #92400E; }
    .news-tag--community { background: #DBEAFE; color: #1E40AF; }
    .news-tag--customers { background: #D1FAE5; color: #065F46; }
    .news-tag--security { background: #FEE2E2; color: #991B1B; }
    .news-tag--company-news { background: #EDE9FE; color: #5B21B6; }
    .news-tag--v0 { background: #FCE7F3; color: #9D174D; }
    .news-tag--changelog { background: #F3F4F6; color: #374151; }
    .news-tag--press { background: #F0FDFA; color: #134E4A; }

    .news-date {
      font-size: 12px;
      color: var(--slate-400);
      margin-bottom: 8px;
    }

    .news-title {
      font-size: 16px;
      font-weight: 700;
      color: var(--navy-900);
      line-height: 1.35;
      margin-bottom: 8px;
      letter-spacing: -0.005em;
    }

    .news-excerpt {
      font-size: 13px;
      color: var(--slate-500);
      line-height: 1.6;
      margin-bottom: 16px;
      flex: 1;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-author {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: auto;
    }

    .news-avatar {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 600;
      background: var(--blue-50);
      color: var(--blue-500);
      flex-shrink: 0;
    }

    .news-author-name {
      font-size: 12px;
      color: var(--slate-500);
      font-weight: 500;
    }

    /* Show more button */
    .show-more-wrapper {
      text-align: center;
      padding: 40px 0 24px;
    }

    .btn-show-more {
      padding: 12px 32px;
      font-size: 14px;
      font-weight: 600;
      color: var(--navy-900);
      background: var(--white);
      border: 1px solid var(--slate-300);
      border-radius: var(--radius-md);
      transition: all var(--transition-fast);
    }

    .btn-show-more:hover {
      border-color: var(--slate-400);
      box-shadow: var(--shadow-sm);
    }

    .btn-show-more:focus-visible {
      outline: 2px solid var(--blue-500);
      outline-offset: 2px;
    }

    .btn-show-more:disabled {
      color: var(--slate-400);
      border-color: var(--slate-200);
      cursor: default;
    }

    /* No results */
    .no-results {
      text-align: center;
      padding: 64px 24px;
      display: none;
    }

    .no-results.visible { display: block; }

    .no-results svg {
      width: 48px;
      height: 48px;
      color: var(--slate-300);
      margin: 0 auto 16px;
    }

    .no-results h3 {
      font-size: 18px;
      font-weight: 600;
      color: var(--slate-700);
      margin-bottom: 8px;
    }

    .no-results p {
      font-size: 14px;
      color: var(--slate-400);
      max-width: 360px;
      margin: 0 auto;
    }

    /* ===== CTA BANNER ===== */
    .cta-section {
      padding: 64px 0;
    }

    .cta-grid {
      display: grid;
      grid-template-columns: 1.4fr 1fr;
      gap: 20px;
    }

    .cta-card {
      border-radius: var(--radius-xl);
      padding: 48px;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }

    .cta-card--primary {
      background: linear-gradient(135deg, #0a1628 0%, #0f2440 100%);
      color: var(--white);
    }

    .cta-card--secondary {
      background: var(--gray-50);
      border: 1px solid var(--slate-200);
    }

    .cta-headline {
      font-size: 26px;
      font-weight: 700;
      line-height: 1.3;
      letter-spacing: -0.01em;
      margin-bottom: 16px;
    }

    .cta-card--primary .cta-headline { color: var(--white); }
    .cta-card--secondary .cta-headline { color: var(--navy-900); }

    .cta-text {
      font-size: 15px;
      line-height: 1.6;
      margin-bottom: 28px;
    }

    .cta-card--primary .cta-text { color: rgba(255,255,255,0.7); }
    .cta-card--secondary .cta-text { color: var(--slate-500); }

    .cta-actions {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }

    .btn-primary {
      padding: 11px 24px;
      font-size: 14px;
      font-weight: 600;
      background: var(--blue-500);
      color: var(--white);
      border-radius: var(--radius-md);
      transition: background var(--transition-fast);
    }

    .btn-primary:hover { background: var(--blue-600); }

    .btn-primary:focus-visible {
      outline: 2px solid var(--blue-500);
      outline-offset: 2px;
    }

    .btn-secondary {
      padding: 11px 24px;
      font-size: 14px;
      font-weight: 600;
      background: rgba(255,255,255,0.1);
      color: var(--white);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: var(--radius-md);
      transition: all var(--transition-fast);
    }

    .btn-secondary:hover {
      background: rgba(255,255,255,0.15);
      border-color: rgba(255,255,255,0.3);
    }

    .btn-outline {
      padding: 11px 24px;
      font-size: 14px;
      font-weight: 600;
      background: var(--white);
      color: var(--navy-900);
      border: 1px solid var(--slate-300);
      border-radius: var(--radius-md);
      transition: all var(--transition-fast);
    }

    .btn-outline:hover {
      border-color: var(--slate-400);
      box-shadow: var(--shadow-sm);
    }

    .cta-card--primary .pro { color: var(--orange-500); font-weight: 700; }
    .cta-card--primary .enterprise { color: #60a5fa; font-weight: 700; }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--navy-900);
      color: rgba(255,255,255,0.7);
      padding: 64px 0 32px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 32px;
      margin-bottom: 48px;
    }

    .footer-col h5 {
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: rgba(255,255,255,0.4);
      margin-bottom: 16px;
    }

    .footer-col ul { display: flex; flex-direction: column; gap: 8px; }

    .footer-col a {
      font-size: 13px;
      color: rgba(255,255,255,0.6);
